SELECT

FROM supplier_sku ss
WHERE ss.deleted = FALSE

    AND ss.supplier_id = #{query.supplierId}


    AND ss.sku_id = #{query.skuId}


    AND ss.status = #{query.status}

mapper.update:
UPDATE supplier_sku
SET deleted    = TRUE,
    version    = version + 1,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{operator}
WHERE supplier_id = #{supplierId}
  AND id = #{id}
  AND version = #{version}
  AND deleted = FALSE
